// src/web/lib/actions.ts
async function runAction(path, opts = {}, afterSuccess) {
  if (opts.confirm && !window.confirm(opts.confirm))
    return;
  try {
    await apiPost(path, opts.body);
    showToast(opts.successMsg || "Done", "info");
    if (afterSuccess)
      await afterSuccess();
  } catch (e4) {
    const err = e4;
    const msg = err.hint ? `${err.message} — ${err.hint}` : err.message || "Action failed";
    showToast(msg, "error");
  }
}
async function copyCmd(cmd) {
  try {
    await navigator.clipboard.writeText(cmd);
    showToast(`Copied: ${cmd}`, "info");
  } catch {
    showToast(`Copy failed — run manually: ${cmd}`, "error");
  }
}

